SELECT 'датчик «migration-table» ' || fact_gap($1, 'migration-table') || ': проверить нечем, и это не зелёное' AS detail WHERE NOT fact_fresh($1, 'migration-table') UNION ALL SELECT t.name || ' — в модели есть, а среди прочитанного датчиком «migration-table» её нет' AS detail FROM project_db_tables t WHERE t.project_id = $1 AND NOT EXISTS (SELECT 1 FROM code_fact f WHERE f.project_id = t.project_id AND f.kind = 'migration-table' AND f.name = t.name) ORDER BY 1
